.sl-hero-reveal {
  background-color: var(--smartlearn-bg);
  color: var(--smartlearn-text);
  font-family: var(--smartlearn-body-font, system-ui, -apple-system, sans-serif);
  min-height: 80vh;
  display: flex;
  align-items: center;
  padding-block: clamp(3.5rem, 7vw, 6rem);
}
.sl-hero-reveal .sl-text-primary { color: var(--smartlearn-primary); }
.sl-hero-reveal .sl-text-emphasis {
  color: var(--smartlearn-text);
  font-family: var(--smartlearn-heading-font, var(--smartlearn-body-font, system-ui, -apple-system, sans-serif));
}
.sl-hero-reveal .sl-text-muted { color: var(--smartlearn-text-muted); }
.sl-hero-reveal .sl-bg-main { background-color: var(--smartlearn-bg); }
.sl-hero-reveal .sl-bg-card { background-color: var(--smartlearn-card-bg); }
.sl-hero-reveal .sl-bg-primary { background-color: var(--smartlearn-primary); }
.sl-hero-reveal .sl-tint-primary {
  background-color: color-mix(in srgb, var(--smartlearn-primary) 15%, transparent);
}
.sl-hero-reveal .sl-btn-primary {
  background-color: var(--smartlearn-btn-bg);
  border: 1px solid var(--smartlearn-btn-bg);
  color: var(--smartlearn-btn-text, #ffffff);
}
.sl-hero-reveal .sl-btn-primary:hover,
.sl-hero-reveal .sl-btn-primary:focus-visible {
  background-color: var(--smartlearn-btn-hover-bg, var(--smartlearn-primary-hover));
  border-color: var(--smartlearn-btn-hover-bg, var(--smartlearn-primary-hover));
  color: var(--smartlearn-btn-text, #ffffff);
}
.sl-hero-reveal .sl-reveal-title {
  letter-spacing: -0.03em;
}
.sl-hero-reveal .sl-hover-lift {
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.sl-hero-reveal .sl-dashboard-mockup {
  border: 2px solid var(--smartlearn-card-border);
  transform: perspective(1000px) rotateY(-12deg) rotateX(4deg) scale(0.94);
  transform-origin: center right;
  box-shadow: -20px 20px 60px rgba(0, 0, 0, 0.12);
}
[dir="rtl"] .sl-hero-reveal .sl-dashboard-mockup {
  transform: perspective(1000px) rotateY(12deg) rotateX(4deg) scale(0.94);
  transform-origin: center left;
}
.sl-hero-reveal .sl-mockup-chrome {
  border-bottom: 1px solid var(--smartlearn-card-border);
}
.sl-hero-reveal .sl-chrome-dot {
  width: 12px;
  height: 12px;
  display: inline-block;
}
.sl-hero-reveal .sl-url-pill {
  font-size: 11px;
  border: 1px solid var(--smartlearn-card-border);
}
.sl-hero-reveal .sl-widget-box {
  border: 1px solid var(--smartlearn-card-border);
}
.sl-hero-reveal .sl-course-icon {
  width: 56px;
  height: 56px;
  flex-shrink: 0;
}
.sl-hero-reveal .sl-progress-track {
  height: 8px;
  background-color: var(--smartlearn-card-bg);
  border: 1px solid var(--smartlearn-card-border);
}
.sl-hero-reveal .sl-goal-ring {
  width: 48px;
  height: 48px;
  flex-shrink: 0;
  border: 3px solid var(--smartlearn-primary);
}
@media (prefers-reduced-motion: no-preference) {
  .sl-hero-reveal .sl-hover-lift:hover {
    transform: translateY(-3px);
    box-shadow: 0 15px 30px color-mix(in srgb, var(--smartlearn-primary) 22%, transparent);
  }
}
@media (prefers-reduced-motion: reduce) {
  .sl-hero-reveal .sl-hover-lift {
    transition: none;
  }
  .sl-hero-reveal .sl-dashboard-mockup,
  [dir="rtl"] .sl-hero-reveal .sl-dashboard-mockup {
    transform: none;
  }
}
@media (max-width: 991px) {
  .sl-hero-reveal .sl-dashboard-mockup,
  [dir="rtl"] .sl-hero-reveal .sl-dashboard-mockup {
    transform: none;
    margin-top: 1.5rem;
  }
}
